import zlib, gzip, bz2, lzma
def solve(data):
    codec = {'zlib':zlib, 'gzip':gzip, 'bz2':bz2, 'lzma':lzma}[data['codec']]
    raw = data['text'].encode('utf-8')
    restored = codec.decompress(codec.compress(raw))
    return {'restored':restored.decode('utf-8'), 'same':restored == raw}
